void Solver::bump_var(int var, double coeff) {
    // Compute increment and add to activity
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Rescale activities if any exceeds a safe bound to avoid overflow
    const double ACT_LIMIT = 1e90;
    if (activity[var] > ACT_LIMIT) {
        const double RESCALE_FACTOR = 1e-90;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= RESCALE_FACTOR;
        }
        var_inc *= RESCALE_FACTOR;
    }

    // Keep the VSIDS heap consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}
